use anyhow::{bail, Context, Result};

use super::super::{provision, CapsuleClosure};

pub(super) fn arguments(
    closure: &CapsuleClosure,
    local: &provision::LocalProvision,
) -> Result<Vec<String>> {
    if closure.script_cid.is_none() {
        return Ok(closure.arguments.clone());
    }
    let prefix = "unicodex.foreign_process.runtime.v";
    let exact_script_runtime = closure
        .runtime_schema
        .strip_prefix(prefix)
        .and_then(|version| version.parse::<u8>().ok())
        .is_some_and(|version| {
            (2..=17).contains(&version) && closure.runtime_schema == format!("{prefix}{version}")
        });
    if !exact_script_runtime
        || !matches!(
            closure.runtime_embedding.as_deref(),
            Some("static_in_executable" | "external_materialized_closure")
        )
    {
        bail!("foreign-process script invocation requires an exact embedded runtime");
    }
    let script_path = provision::sandbox_script_path(local)?;
    let script = script_path
        .to_str()
        .context("foreign-process sandbox script path must be UTF-8")?;
    let runtime = script_path
        .parent()
        .context("foreign-process runtime support root is unavailable")?
        .to_str()
        .context("foreign-process runtime support root must be UTF-8")?;
    let binds_runtime = matches!(
        closure.runtime_schema.as_str(),
        super::super::value::RUNTIME_SCHEMA_V16 | super::super::value::RUNTIME_SCHEMA_V17
    );
    super::path_binding::replace(&closure.arguments, script, runtime, binds_runtime)
}

